"use client";

import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import type { Run } from "@/lib/mock-data";

const statusVariant: Record<Run["status"], "success" | "error" | "info" | "warning"> = {
  success: "success",
  failed: "error",
  running: "info",
  killed: "warning",
};

interface RunTableProps {
  runs: Run[];
}

export function RunTable({ runs }: RunTableProps) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-border text-left">
            <th className="pb-2 pr-4 text-xs font-medium text-text-secondary">
              Status
            </th>
            <th className="pb-2 pr-4 text-xs font-medium text-text-secondary">
              Started
            </th>
            <th className="pb-2 pr-4 text-xs font-medium text-text-secondary">
              Finished
            </th>
            <th className="pb-2 pr-4 text-xs font-medium text-text-secondary">
              Duration
            </th>
            <th className="pb-2 pr-4 text-xs font-medium text-text-secondary">
              Exit Code
            </th>
            <th className="pb-2 text-xs font-medium text-text-secondary text-right">
              Cost
            </th>
          </tr>
        </thead>
        <tbody>
          {runs.map((run) => (
            <tr
              key={run.id}
              className="border-b border-border/50 hover:bg-surface-elevated/30 transition-colors"
            >
              <td className="py-2.5 pr-4">
                <Badge variant={statusVariant[run.status]}>
                  {run.status}
                </Badge>
              </td>
              <td className="py-2.5 pr-4 font-mono text-xs text-text-secondary">
                {run.started}
              </td>
              <td className="py-2.5 pr-4 font-mono text-xs text-text-secondary">
                {run.finished}
              </td>
              <td className="py-2.5 pr-4 font-mono text-xs text-text-primary">
                {run.duration}
              </td>
              <td className="py-2.5 pr-4">
                <span
                  className={cn(
                    "font-mono text-xs",
                    run.exitCode === 0
                      ? "text-success"
                      : run.exitCode === null
                        ? "text-info"
                        : "text-error"
                  )}
                >
                  {run.exitCode === null ? "--" : run.exitCode}
                </span>
              </td>
              <td className="py-2.5 font-mono text-xs text-text-primary text-right">
                {run.cost}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
