"use client";

import { Badge } from "@/components/ui/badge";
import { Card, CardHeader, CardTitle } from "@/components/ui/card";
import { RunTable } from "./run-table";
import { jobs, runs, type JobStatus } from "@/lib/mock-data";

const statusBadge: Record<
  JobStatus,
  { variant: "success" | "error" | "info" | "neutral"; label: string }
> = {
  ok: { variant: "success", label: "Healthy" },
  failed: { variant: "error", label: "Failed" },
  running: { variant: "info", label: "Running" },
  disabled: { variant: "neutral", label: "Disabled" },
};

interface JobDetailProps {
  jobId: string;
}

function ConfigRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-start py-2.5 border-b border-border/30 last:border-0">
      <dt className="w-36 flex-shrink-0 text-xs font-medium text-text-secondary">
        {label}
      </dt>
      <dd className="text-sm font-mono text-text-primary break-all">
        {value}
      </dd>
    </div>
  );
}

export function JobDetail({ jobId }: JobDetailProps) {
  const job = jobs.find((j) => j.id === jobId);
  if (!job) return null;

  const jobRuns = runs.filter((r) => r.jobId === jobId);
  const badge = statusBadge[job.status];

  const envVarStr =
    Object.keys(job.envVars).length > 0
      ? Object.entries(job.envVars)
          .map(([k, v]) => `${k}=${v}`)
          .join("\n")
      : "None";

  return (
    <div className="flex-1 overflow-y-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <h1 className="text-xl font-semibold text-text-primary">{job.name}</h1>
        <Badge variant={badge.variant}>{badge.label}</Badge>
      </div>

      {/* Configuration */}
      <Card>
        <CardHeader>
          <CardTitle>Configuration</CardTitle>
        </CardHeader>
        <dl>
          <ConfigRow label="Schedule" value={job.schedule || "None"} />
          <ConfigRow label="Schedule Mode" value={job.scheduleMode} />
          <ConfigRow label="Command" value={job.command} />
          <ConfigRow label="Working Dir" value={job.workingDir} />
          <ConfigRow label="Shell" value={job.shell} />
          <ConfigRow label="Timeout" value={job.timeout} />
          <ConfigRow label="Max Retries" value={String(job.maxRetries)} />
          <ConfigRow
            label="Allow Concurrent"
            value={job.allowConcurrent ? "Yes" : "No"}
          />
          <ConfigRow label="Pre-hook" value={job.preHook || "None"} />
          <ConfigRow label="Post-hook" value={job.postHook || "None"} />
          <ConfigRow label="Env Vars" value={envVarStr} />
          <ConfigRow label="Created" value={job.created} />
          <ConfigRow label="Last Run" value={job.lastRun} />
        </dl>
      </Card>

      {/* Run History */}
      <Card>
        <CardHeader>
          <CardTitle>Run History</CardTitle>
        </CardHeader>
        {jobRuns.length === 0 ? (
          <p className="text-sm text-text-secondary">No runs yet.</p>
        ) : (
          <RunTable runs={jobRuns} />
        )}
      </Card>
    </div>
  );
}
